    private class MainAdapter extends BaseAdapter {

        @Override
        public int getCount() {
            return arrayList.size();
        }

        @Override
        public Object getItem(int position) {
            return null;
        }

        @Override
        public long getItemId(int position) {
            return 0;
        }

        @Override
        public View getView(int position, View convertView, ViewGroup parent) {
            LayoutInflater inflater = getLayoutInflater();
            View mainView = inflater.inflate(R.layout.list_status2, parent, false);
            @SuppressLint({"MissingInflatedId", "LocalSuppress"})
            TextView textView = mainView.findViewById(R.id.item_text2);
            Button copyBoardId = mainView.findViewById(R.id.copyButton2);
            Button download_query = mainView.findViewById(R.id.download_query);
            Button shareStatus2 = mainView.findViewById(R.id.shareStatus2);
            RelativeLayout bg_random_color = mainView.findViewById(R.id.bg_random_color);


            hashMap = arrayList.get(position);
            String mainList = hashMap.get("status");

            textView.setText(mainList);


            //copy============================
            copyBoardId.setOnClickListener(new View.OnClickListener() {
                @Override
                public void onClick(View v) {

                    copyToClipboard(mainList);
                }
            });

            //download========================================
            download_query.setOnClickListener(new View.OnClickListener() {
                @Override
                public void onClick(View v) {
                    // LinearLayout কে bitmap করা হয়েছে।
                    AdHelper.showAdIfNeeded(Bio_three_activity.this, () -> {
                        Bitmap bitmap = getBitmapFromView(bg_random_color);

                        if (myPermissions()) {
                            saveImage(bitmap);
                        }
                    });
                }
            });


            //share content==========================
            shareStatus2.setOnClickListener(new View.OnClickListener() {
                @Override
                public void onClick(View v) {
                    Intent sendIntent = new Intent();
                    sendIntent.setAction(Intent.ACTION_SEND);
                    sendIntent.putExtra(Intent.EXTRA_TEXT, mainList);
                    sendIntent.setType("text/plain");
                    sendIntent.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
                    Intent shareIntent = Intent.createChooser(sendIntent, "Share By");
                    shareIntent.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
                    startActivity(sendIntent);
                }
            });


            return mainView;
        }
        // View থেকে Bitmap তৈরি করার নতুন পদ্ধতি
        private Bitmap getBitmapFromView(View view) {
            Bitmap bitmap = Bitmap.createBitmap(view.getWidth(), view.getHeight(), Bitmap.Config.ARGB_8888);
            Canvas canvas = new Canvas(bitmap);
            view.draw(canvas);
            return bitmap;
        }
    }

